#!/usr/bin/env python3
# THE NUMBERS WALK sitting 2 — NASO (2026-09-09): THE CLAIMS of Numbers 4:21-7:89, seven manifests (one per draft unit), read off the
# seven ledgers of this sitting, every claim LABELED (World/step9/CLAIM_LABELS.md's vocabulary), a machine check where the ink allows —
# every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS (sitting 1's form,
# write_bamidbar_manifests.py). Claim IDs per unit: NS04A (Gershon and Merari), NS05A (the camp and the theft), NS05B (the suspected
# wife), NS06A (the Nazirite), NS06B (the blessing), NS07A (the wagons and the first six days), NS07B (the last six, the totals, the Voice).
# Written once (the files must not exist). Every source cite is checked against its ledger's CITE INDEX before a byte is written.
import json, os, re, sqlite3
ROOT = _ROOT
DATE = '2026-09-09'
UNITS = {'num_04_gershon_merari': 'NS04A', 'num_05_camp_pure_theft': 'NS05A', 'num_05_sotah': 'NS05B', 'num_06_nazir': 'NS06A',
         'num_06_priest_blessing': 'NS06B', 'num_07_carts_offerings_a': 'NS07A', 'num_07_offerings_b_total': 'NS07B'}
OUT = {u: f'{ROOT}/logic/oral_audit/manifests/{u}_claims.json' for u in UNITS}
for o in OUT.values(): assert not os.path.exists(o), o
CI = {}
for u in UNITS:
    led = open(f'{ROOT}/logic/oral_triage/{u}_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
    CI[u] = set(re.findall(r'^(Sifrei Bamidbar \d+:\d+|Onkelos Num \d+:\d+)$', led, re.M))
assert sum(len(v) for v in CI.values()) == 257, {u: len(v) for u, v in CI.items()}
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, n, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth and (len(hit) == 1 or nth is not None), (book, ch, v, word, hit)   # a doubled word: the nth occurrence, named
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    n = min(len(piece), max(n, 6))   # at least six code points of the pointed stem, never past the stem
    return idx, piece[:n]
def hc(ref, word, n, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, n, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Num {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Bamidbar {r}' for r in rows)

