n_claims = n_checks = 0
for u, cs in C.items():
    ids = [c['id'] for c in cs]; assert len(set(ids)) == len(ids) and all(i.startswith(UNITS[u] + '-') for i in ids), ids
    for c in cs:
        for s in c['source'].split('; '): assert s in CI[u], (u, c['id'], s)
        assert re.match(r'^(plain|ink|I\d+|E\d+|M-\d+|H)( \(.*\))?$', c['middah']), (c['id'], c['middah'])
        n_claims += 1; n_checks += 1 if c.get('check') else 0
    open(OUT[u], 'w', encoding='utf-8').write(json.dumps(cs, indent=1, ensure_ascii=False) + '\n')
    print(f'wrote {OUT[u]}: {len(cs)} claims')
assert n_claims == 51 and n_checks == 51, (n_claims, n_checks)   # the script's count (the hand had said 52; the sotah carries eleven)
print(f'NASO: {n_claims} claims, {n_checks} checks across {len(C)} manifests')
